<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core/PublicPage.php';require dirname(__DIR__).'/app/Core/Database.php';$docs=[];$items=[];$error=null;$search=trim((string)($_GET['q']??''));
try{$db=Database::connection();$like='%'.$search.'%';$q=$db->prepare("SELECT title,description,document_url,published_date FROM public_documents WHERE status='PUBLISHED' AND category='LAW_OR_ISSUANCE' AND (:empty=1 OR title LIKE :q1 OR description LIKE :q2) ORDER BY published_date DESC");$q->execute(['empty'=>$search===''?1:0,'q1'=>$like,'q2'=>$like]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare("SELECT title,summary,body,slug,published_at FROM content_items WHERE status='PUBLISHED' AND content_type='ISSUANCE' AND (:empty=1 OR title LIKE :q1 OR summary LIKE :q2 OR body LIKE :q3) ORDER BY published_at DESC");$q->execute(['empty'=>$search===''?1:0,'q1'=>$like,'q2'=>$like,'q3'=>$like]);$items=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Laws page: '.$e->getMessage());$error='Public issuances are temporarily unavailable.';}
pageHeader('Laws & Issuances','Published barangay ordinances, resolutions, and public issuances.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">PUBLIC RECORDS</p><h1>Laws &amp; Issuances</h1><p>Search and review public ordinances, resolutions, and dated issuances after they have been officially published.</p></div></section><section class="section"><form class="portal-form" method="get" action="<?= Security::e(url('laws.php')) ?>"><label>Search laws and issuances<input name="q" value="<?= Security::e($search) ?>" placeholder="Search title or content"></label><button class="action-primary" type="submit">Search</button></form><?php if($error): ?><div class="notice warning"><?= Security::e($error) ?></div><?php elseif(!$docs&&!$items): ?><div class="publication-empty"><h2>No verified issuances have been published</h2><p>Official copies and dates will be displayed here after publication by authorized staff.</p></div><?php endif; ?><?php foreach($items as $r): ?><article class="workflow-card"><p class="eyebrow">ISSUANCE · <?= Security::e($r['published_at']) ?></p><h2><?= Security::e($r['title']) ?></h2><p><?= Security::e($r['summary']??'') ?></p><p><?= nl2br(Security::e($r['body'])) ?></p></article><?php endforeach; ?><?php foreach($docs as $r): ?><article class="workflow-card"><p class="eyebrow">PUBLIC RECORD · <?= Security::e($r['published_date']??'Date not specified') ?></p><h2><?= Security::e($r['title']) ?></h2><p><?= Security::e($r['description']??'') ?></p><?php if($r['document_url']): ?><a class="learn" href="<?= Security::e($r['document_url']) ?>" target="_blank" rel="noopener noreferrer">Open document ↗</a><?php endif; ?></article><?php endforeach; ?></section></main><?php pageFooter();
